package com.gregtech.gregtech.registry;
import com.gregtech.gregtech.block.misc.PileBlock;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.neoforged.neoforge.registries.DeferredHolder;
public final class GTMaterialPiles {private GTMaterialPiles(){}public static DeferredHolder<Block,PileBlock> INGOT_PILE,PLATE_PILE,PLATE_GEM_PILE;public static java.util.List<DeferredHolder<Block,PileBlock>> all(){return java.util.List.of(INGOT_PILE,PLATE_PILE,PLATE_GEM_PILE);}public static void initialize(){INGOT_PILE=reg("ingot_pile",PileBlock.Kind.INGOT,MapColor.METAL);PLATE_PILE=reg("plate_pile",PileBlock.Kind.PLATE,MapColor.METAL);PLATE_GEM_PILE=reg("plate_gem_pile",PileBlock.Kind.GEM_PLATE,MapColor.DIAMOND);}private static DeferredHolder<Block,PileBlock> reg(String id,PileBlock.Kind kind,MapColor color){var b=GTBlocks.BLOCKS.register(id,()->new PileBlock(kind,BlockBehaviour.Properties.of().mapColor(color).strength(.25f,0).sound(SoundType.METAL).noOcclusion().isSuffocating((s,l,p)->false)));GTBlocks.BLOCK_ITEMS.register(id,()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties()));return b;}}
